"""本地客服工单中心命令行入口。

支持工单的创建、查看与结案，数据存储于本地 SQLite 文件。
"""

import argparse
import json
import sqlite3
import sys

DEFAULT_DB = "tickets.sqlite"


def connect(db_path):
    """打开（必要时创建）数据库并确保工单表存在。"""
    conn = sqlite3.connect(db_path)
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS tickets (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            title TEXT NOT NULL,
            description TEXT NOT NULL,
            status TEXT NOT NULL
        )
        """
    )
    conn.commit()
    return conn


def print_ticket(ticket):
    """将工单作为唯一 JSON 对象输出到标准输出。"""
    print(json.dumps(ticket, ensure_ascii=False))


def create_ticket(conn, title, description):
    title = title.strip()
    if not title:
        print("标题不能为空", file=sys.stderr)
        return 1

    cursor = conn.execute(
        "INSERT INTO tickets (title, description, status) VALUES (?, ?, ?)",
        (title, description, "open"),
    )
    conn.commit()
    print_ticket(
        {
            "id": cursor.lastrowid,
            "title": title,
            "description": description,
            "status": "open",
        }
    )
    return 0


def find_ticket(conn, raw_id):
    """校验编号并查找工单；失败时打印错误并返回 None。"""
    try:
        ticket_id = int(raw_id)
    except (TypeError, ValueError):
        ticket_id = None
    if ticket_id is None or ticket_id <= 0:
        print("工单编号必须为正整数", file=sys.stderr)
        return None

    row = conn.execute(
        "SELECT id, title, description, status FROM tickets WHERE id = ?",
        (ticket_id,),
    ).fetchone()
    if row is None:
        print("工单不存在", file=sys.stderr)
        return None
    return row


def row_to_ticket(row):
    """将查询行转换为对外输出的工单字典。"""
    return {
        "id": row[0],
        "title": row[1],
        "description": row[2],
        "status": row[3],
    }


def show_ticket(conn, raw_id):
    row = find_ticket(conn, raw_id)
    if row is None:
        return 1

    print_ticket(row_to_ticket(row))
    return 0


def close_ticket(conn, raw_id):
    row = find_ticket(conn, raw_id)
    if row is None:
        return 1

    conn.execute("UPDATE tickets SET status = ? WHERE id = ?", ("closed", row[0]))
    conn.commit()

    ticket = row_to_ticket(row)
    ticket["status"] = "closed"
    print_ticket(ticket)
    return 0


def reopen_ticket(conn, raw_id):
    row = find_ticket(conn, raw_id)
    if row is None:
        return 1

    conn.execute("UPDATE tickets SET status = ? WHERE id = ?", ("open", row[0]))
    conn.commit()

    ticket = row_to_ticket(row)
    ticket["status"] = "open"
    print_ticket(ticket)
    return 0


def list_tickets(conn, status):
    if status is None:
        rows = conn.execute(
            "SELECT id, title, description, status FROM tickets ORDER BY id"
        ).fetchall()
    else:
        rows = conn.execute(
            "SELECT id, title, description, status FROM tickets "
            "WHERE status = ? ORDER BY id",
            (status,),
        ).fetchall()

    tickets = [
        {
            "id": row[0],
            "title": row[1],
            "description": row[2],
            "status": row[3],
        }
        for row in rows
    ]
    print(json.dumps(tickets, ensure_ascii=False))
    return 0


def build_parser():
    parser = argparse.ArgumentParser(description="本地客服工单中心")
    parser.add_argument(
        "--db",
        default=DEFAULT_DB,
        help="SQLite 数据库文件路径（默认：当前工作目录下的 tickets.sqlite）",
    )
    subparsers = parser.add_subparsers(dest="command", required=True)

    create_parser = subparsers.add_parser("create", help="创建工单")
    create_parser.add_argument("--title", default="", help="工单标题")
    create_parser.add_argument(
        "--description", default="", help="工单描述（可为空字符串）"
    )

    show_parser = subparsers.add_parser("show", help="按编号查看工单")
    show_parser.add_argument("id", help="工单编号（正整数）")

    close_parser = subparsers.add_parser("close", help="按编号结案工单")
    close_parser.add_argument("id", help="工单编号（正整数）")

    reopen_parser = subparsers.add_parser("reopen", help="按编号重新打开工单")
    reopen_parser.add_argument("id", help="工单编号（正整数）")

    list_parser = subparsers.add_parser("list", help="列出工单")
    list_parser.add_argument(
        "--status",
        choices=["open", "closed"],
        default=None,
        help="按状态筛选（open 或 closed；不传则返回全部工单）",
    )

    return parser


def main(argv=None):
    parser = build_parser()
    args = parser.parse_args(argv)

    conn = connect(args.db)
    try:
        if args.command == "create":
            return create_ticket(conn, args.title, args.description)
        if args.command == "show":
            return show_ticket(conn, args.id)
        if args.command == "close":
            return close_ticket(conn, args.id)
        if args.command == "reopen":
            return reopen_ticket(conn, args.id)
        if args.command == "list":
            return list_tickets(conn, args.status)
        return 1
    finally:
        conn.close()


if __name__ == "__main__":
    sys.exit(main())

    result = self.run_cli("create", *args)
    self.assertEqual(result.returncode, 0, f"准备样例失败: {result.stderr}")
    self.assertEqual(result.stderr, "")
    return self._parse_object(result.stdout)

@staticmethod
def _parse_object(stdout):
    decoder = json.JSONDecoder()
    stripped = stdout.lstrip()
    value, end = decoder.raw_decode(stripped)
    if not isinstance(value, dict) or stripped[end:].strip() != "":
        raise AssertionError(f"标准输出不是唯一 JSON 对象: {stdout!r}")
    return value

def ticket_rows(self):
    conn = sqlite3.connect(self.db_path)
    try:
        return conn.execute(
            "SELECT id, title, description, status FROM tickets ORDER BY id"
        ).fetchall()
    finally:
        conn.close()

def assert_storage_unchanged(self):
    """失败查询不新增工单，也不改变已有记录。"""
    self.assertEqual(
        [list(row) for row in self.ticket_rows()], self.expected_rows
    )

# ---------- 编号格式错误 ----------

def test_show_rejects_non_positive_integer_ids(self):
    for bad_id in ("abc", "0", "-1"):
        with self.subTest(bad_id=bad_id):
            result = self.run_cli("show", bad_id)
            self.assertEqual(result.returncode, 1)
            self.assertEqual(result.stdout, "")
            # 错误只写标准错误，仅为提示语加末尾换行
            self.assertEqual(result.stderr, "工单编号必须为正整数\n")
            self.assert_storage_unchanged()

# ---------- 编号不存在 ----------

def test_show_reports_missing_ticket(self):
    result = self.run_cli("show", "999")
    self.assertEqual(result.returncode, 1)
    self.assertEqual(result.stdout, "")
    self.assertEqual(result.stderr, "工单不存在\n")
    self.assert_storage_unchanged()

# ---------- 参数用法错误 ----------

def test_show_usage_errors_exit_with_code_2(self):
    for argv in (
        ("show",),
        ("show", str(self.first["id"]), "--unknown"),
    ):
        with self.subTest(argv=argv):
            result = self.run_cli(*argv)
            self.assertEqual(result.returncode, 2)

